import Script from "next/script";
import { adsenseClientId, adsenseEnabled } from "@/lib/adsense";

/**
 * One AdSense bootstrap per ad-bearing editorial guide document, with the
 * exact nonce generated by middleware for that response. Never mount globally:
 * token-bearing buyer/account routes must not inherit advertising scripts.
 */
export function AdSense({ nonce }: { nonce?: string }) {
  const clientId = adsenseClientId();
  // A client-side RSC transition may lack a document nonce. In that case,
  // fail closed instead of inserting an external script under the old CSP.
  if (!adsenseEnabled() || !clientId || !nonce) return null;

  return <Script
    id="motoindex-adsense"
    async
    nonce={nonce}
    strategy="afterInteractive"
    crossOrigin="anonymous"
    src={`https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=${clientId}`}
  />;
}
